from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject


class Flags(SchemaObject):
    cancelled = SchemaField(name="Cancelled")
    historical = SchemaField(name="Historical")

    def __init__(self, cancelled, historical):
        self.cancelled = cancelled
        self.historical = historical
        super().__init__()


class Alarms(SchemaObject):
    id = SchemaField(name="id")
    fault_id = SchemaField(name="faultId")
    name = SchemaField(name="name")
    number = SchemaField(name="number")
    severity = SchemaField(name="severity")
    event_time = SchemaField(name="eventTime")
    event_cancellation_time = SchemaField(name="eventCancellationTime")
    description = SchemaField(name="description")
    flags = SchemaField(name="flags", klass=Flags)

    def __init__(
        self,
        id,
        fault_id,
        name,
        number,
        severity,
        event_time,
        event_cancellation_time,
        description,
        flags,
    ):
        self.id = id
        self.fault_id = fault_id
        self.name = name
        self.number = number
        self.severity = severity
        self.event_time = event_time
        self.event_cancellation_time = event_cancellation_time
        self.description = description
        self.flags = flags

        super().__init__()
